using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Media;using System.Windows.Shapes;using FacialPresets;using DanceStudio;
namespace FacialStudio;
public sealed class KeyTimeline:Grid {
 readonly Func<FacialClip> clip;readonly Func<double> cursor;readonly Action<double> seek,add;readonly Action<FacialKey> select;readonly Action begin,commit,cancel;
 readonly Grid plot=new(){Background=StudioTheme.Background,ClipToBounds=true};readonly Canvas ticks=new(){IsHitTestVisible=false},markers=new(){IsHitTestVisible=false};readonly Line head=new(){Y1=25,Y2=120,Stroke=Brushes.White,StrokeThickness=2,IsHitTestVisible=false};readonly ScrollBar scroll=new(){Orientation=Orientation.Horizontal,Minimum=0,Height=18};
 readonly Dictionary<Guid,(Polygon dot,TextBlock label)> visuals=new();FacialKey[] ordered=[];FacialKey? drag;Guid? selected;bool scrubbing,finishing,updatingBar;double originalTime;bool followPlayback=true;const double Left=22,Right=24;
 public ClipViewport Viewport{get;}=new();public event Action<bool>? FollowChanged;public event Action<FacialKey?,double>? ContextRequested;public event Action? ViewChanged;
 public int TickBuilds{get;private set;}public int KeyBuilds{get;private set;}public int HeadUpdates{get;private set;}public ScrollBar Scroll=>scroll;
 public bool FollowPlayback{get=>followPlayback;set{if(followPlayback==value)return;followPlayback=value;FollowChanged?.Invoke(value);}}
 double Plot=>Math.Max(1,plot.ActualWidth-Left-Right);public double X(double time)=>Left+Viewport.Ratio(time)*Plot;public double TimeAt(double x)=>Viewport.At((x-Left)/Plot);
 public KeyTimeline(Func<FacialClip> get,Func<double> position,Action<double> onSeek,Action<double> onAdd,Action<FacialKey> onSelect,Action onBegin,Action onCommit,Action onCancel){clip=get;cursor=position;seek=onSeek;add=onAdd;select=onSelect;begin=onBegin;commit=onCommit;cancel=onCancel;Height=140;MinHeight=140;Focusable=true;RowDefinitions.Add(new(){Height=new GridLength(1,GridUnitType.Star)});RowDefinitions.Add(new(){Height=GridLength.Auto});Children.Add(plot);plot.Children.Add(ticks);plot.Children.Add(markers);plot.Children.Add(head);SetRow(scroll,1);Children.Add(scroll);
  Viewport.Changed+=()=>{UpdateBar();DrawTicks();PositionKeys();UpdateCursor();ViewChanged?.Invoke();};plot.SizeChanged+=(_,_)=>{DrawTicks();PositionKeys();UpdateCursor();};scroll.ValueChanged+=(_,_)=>{if(updatingBar)return;FollowPlayback=false;Viewport.Pan(scroll.Value);};
  PreviewMouseWheel+=(_,e)=>{Wheel(e.GetPosition(plot).X,e.Delta,(Keyboard.Modifiers&ModifierKeys.Alt)!=0);e.Handled=true;};
  plot.MouseLeftButtonDown+=(_,e)=>{Focus();var at=e.GetPosition(plot);if((Keyboard.Modifiers&ModifierKeys.Control)!=0){add(TimeAt(at.X));e.Handled=true;return;}drag=Hit(at);if(drag!=null){select(drag);SelectMarker(drag.Id);originalTime=drag.Time;begin();}else{scrubbing=true;SelectMarker(null);seek(TimeAt(at.X));}plot.CaptureMouse();e.Handled=true;};
  plot.MouseMove+=(_,e)=>{if(!plot.IsMouseCaptured)return;var at=e.GetPosition(plot);if(drag!=null){MoveKey(drag,TimeAt(at.X));select(drag);ToolTip=$"{drag.Time:0.000} s";}else if(scrubbing)seek(TimeAt(at.X));e.Handled=true;};
  plot.MouseLeftButtonUp+=(_,e)=>{if(!plot.IsMouseCaptured)return;var key=drag;drag=null;scrubbing=false;finishing=true;plot.ReleaseMouseCapture();finishing=false;if(key!=null){commit();select(key);}e.Handled=true;};
  plot.LostMouseCapture+=(_,_)=>{if(finishing)return;if(drag!=null){drag=null;cancel();seek(originalTime);}scrubbing=false;Render();};
  plot.MouseRightButtonUp+=(_,e)=>{var at=e.GetPosition(plot);Focus();ContextRequested?.Invoke(Hit(at),TimeAt(at.X));e.Handled=true;};
  PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape&&plot.IsMouseCaptured){plot.ReleaseMouseCapture();e.Handled=true;}else if(!scroll.IsKeyboardFocusWithin&&(e.Key==Key.Up||e.Key==Key.Down)){SelectAdjacent(e.Key==Key.Up?-1:1);e.Handled=true;}};Viewport.SetDuration(clip().Duration,true);Render();
 }
 public void Wheel(double x,int delta,bool alt){FollowPlayback=false;if(alt)Viewport.Zoom(Viewport.Span*Math.Exp(-delta*.0025),Math.Clamp((x-Left)/Plot,0,1));else Viewport.Pan(Viewport.Start-delta/120d*Viewport.Span*.12);}
 public void Fit()=>Viewport.Fit();
 public void ResetView(){selected=null;Viewport.SetDuration(clip().Duration,true);Render();}
 public void Reveal(double time){if(time<Viewport.Start||time>Viewport.End)Viewport.Pan(time-Viewport.Span*.5);UpdateCursor();}
 public FacialKey? Hit(Point at)=>Math.Abs(at.Y-75)>20?null:ordered.Where(k=>k.Time>=Viewport.Start&&k.Time<=Viewport.End&&Math.Abs(X(k.Time)-at.X)<=9).OrderBy(k=>Math.Abs(X(k.Time)-at.X)).ThenBy(k=>k.Id==selected?0:1).ThenBy(k=>k.Time).ThenBy(k=>k.Id).FirstOrDefault();
 public void SelectAdjacent(int direction){if(ordered.Length==0)return;int index=Array.FindIndex(ordered,k=>k.Id==selected);index=index<0?(direction>0?0:ordered.Length-1):Math.Clamp(index+direction,0,ordered.Length-1);var key=ordered[index];select(key);SelectMarker(key.Id);Reveal(key.Time);}
 public void SelectMarker(Guid? id){if(selected==id)return;if(selected is {} old&&visuals.TryGetValue(old,out var v))v.dot.Fill=StudioTheme.Accent;selected=id;if(id is {} next&&visuals.TryGetValue(next,out v))v.dot.Fill=Brushes.White;}
 public void MoveKey(FacialKey key,double time){if(!double.IsFinite(time)||!clip().Keys.Contains(key))throw new System.IO.InvalidDataException("Invalid key move");var keys=clip().Keys.OrderBy(k=>k.Time).ToArray();int index=Array.IndexOf(keys,key);double min=index>0?Math.BitIncrement(keys[index-1].Time):0,max=index+1<keys.Length?Math.BitDecrement(keys[index+1].Time):clip().Duration;key.Time=Math.Clamp(time,min,Math.Max(min,max));ordered=keys;PositionKeys();}
 public void UpdateCursor(bool playback=false){HeadUpdates++;double position=cursor();if(playback&&FollowPlayback&&(position<Viewport.Start||position>Viewport.End))Viewport.Pan(position-Viewport.Span*.15);double x=X(position);head.X1=head.X2=x;head.Visibility=position>=Viewport.Start&&position<=Viewport.End?Visibility.Visible:Visibility.Hidden;}
 public void Render(){KeyBuilds++;if(Viewport.Duration!=clip().Duration)Viewport.SetDuration(clip().Duration);ordered=clip().Keys.OrderBy(k=>k.Time).ToArray();var ids=ordered.Select(k=>k.Id).ToHashSet();foreach(var id in visuals.Keys.Where(id=>!ids.Contains(id)).ToArray()){var old=visuals[id];markers.Children.Remove(old.dot);markers.Children.Remove(old.label);visuals.Remove(id);}foreach(var k in ordered){if(!visuals.TryGetValue(k.Id,out var v)){var dot=new Polygon{Points=new PointCollection{new(0,-8),new(8,0),new(0,8),new(-8,0)},Stroke=Brushes.White,StrokeThickness=.5,IsHitTestVisible=false};var text=new TextBlock{Foreground=StudioTheme.Muted,FontSize=10,IsHitTestVisible=false};v=(dot,text);visuals[k.Id]=v;markers.Children.Add(dot);markers.Children.Add(text);}v.dot.Fill=k.Id==selected?Brushes.White:StudioTheme.Accent;v.label.Text=k.Interpolation;}PositionKeys();UpdateCursor();}
 void PositionKeys(){for(int i=0;i<ordered.Length;i++){var k=ordered[i];if(!visuals.TryGetValue(k.Id,out var v))continue;bool visible=k.Time>=Viewport.Start&&k.Time<=Viewport.End;v.dot.Visibility=visible?Visibility.Visible:Visibility.Hidden;bool label=visible&&(i+1==ordered.Length||X(ordered[i+1].Time)-X(k.Time)>65);v.label.Visibility=label?Visibility.Visible:Visibility.Hidden;if(!visible)continue;Canvas.SetLeft(v.dot,X(k.Time));Canvas.SetTop(v.dot,75);Canvas.SetLeft(v.label,Math.Min(X(k.Time)+8,Math.Max(0,plot.ActualWidth-58)));Canvas.SetTop(v.label,90);}}
 void UpdateBar(){updatingBar=true;scroll.Maximum=Viewport.Maximum;scroll.ViewportSize=Viewport.Span;scroll.SmallChange=Viewport.Span*.1;scroll.LargeChange=Viewport.Span*.8;scroll.Value=Viewport.Start;scroll.IsEnabled=Viewport.Maximum>0;updatingBar=false;}
 void DrawTicks(){TickBuilds++;ticks.Children.Clear();if(plot.ActualWidth<=0)return;double raw=Viewport.Span/Math.Max(2,Plot/100),power=Math.Pow(10,Math.Floor(Math.Log10(raw))),step=new[]{1d,2,5,10}.Select(n=>n*power).First(n=>n>=raw);for(double time=Math.Ceiling(Viewport.Start/step)*step;time<=Viewport.End+step*1e-7;time+=step){double x=X(time);ticks.Children.Add(new Line{X1=x,X2=x,Y1=30,Y2=120,Stroke=StudioTheme.Line,IsHitTestVisible=false});var text=new TextBlock{Text=time.ToString("0.###")+"s",Foreground=StudioTheme.Muted,FontSize=11,IsHitTestVisible=false};Canvas.SetLeft(text,Math.Clamp(x-10,0,Math.Max(0,plot.ActualWidth-45)));Canvas.SetTop(text,10);ticks.Children.Add(text);}}
}
